inline std::string sha256(const std::string& text){HCRYPTPROV provider=0;HCRYPTHASH hash=0;std::string out;try{if(!CryptAcquireContextW(&provider,nullptr,nullptr,PROV_RSA_AES,CRYPT_VERIFYCONTEXT)||!CryptCreateHash(provider,CALG_SHA_256,0,0,&hash)||!CryptHashData(hash,(BYTE*)text.data(),DWORD(text.size()),0))throw std::runtime_error("동의 문서 해시 계산 실패");BYTE digest[32];DWORD n=32;if(!CryptGetHashParam(hash,HP_HASHVAL,digest,&n,0)||n!=32)throw std::runtime_error("동의 문서 해시 오류");const char* hex="0123456789abcdef";for(BYTE value:digest){out+=hex[value>>4];out+=hex[value&15];}}catch(...){if(hash)CryptDestroyHash(hash);if(provider)CryptReleaseContext(provider,0);throw;}CryptDestroyHash(hash);CryptReleaseContext(provider,0);return out;}
inline std::string deviceUuid(){GUID g;check(CoCreateGuid(&g),"기기 ID 생성 실패");g.Data3=(g.Data3&0x0fff)|0x4000;g.Data4[0]=(g.Data4[0]&0x3f)|0x80;wchar_t value[40];StringFromGUID2(g,value,40);auto text=utf8(value);text=text.substr(1,text.size()-2);std::transform(text.begin(),text.end(),text.begin(),[](char c){return char(std::tolower((unsigned char)c));});return text;}
struct DeviceIdentity {
 fs::path path;json state;std::string uuid;
 explicit DeviceIdentity(const fs::path& root):path(root/"config/client_identity.bin"){
  if(fs::exists(path)){auto encrypted=readFile(path);if(encrypted.size()>1024*1024)throw std::runtime_error("기기 ID 파일 크기 오류");DATA_BLOB in{DWORD(encrypted.size()),(BYTE*)encrypted.data()},out{};if(!CryptUnprotectData(&in,nullptr,nullptr,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&out))throw std::runtime_error("이 Windows 사용자로 기기 ID를 복호화할 수 없습니다.");try{state=json::parse(std::string((char*)out.pbData,out.cbData));}catch(...){LocalFree(out.pbData);throw;}LocalFree(out.pbData);uuid=str(state,"client_id");if(!std::regex_match(uuid,std::regex("[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}")))throw std::runtime_error("기기 ID 형식 오류");}
  else {uuid=deviceUuid();state={{"client_id",uuid},{"consents",json::object()}};save();}
 }
 void save(){auto text=state.dump();DATA_BLOB in{DWORD(text.size()),(BYTE*)text.data()},out{};if(!CryptProtectData(&in,L"snuwcanvas device identity",nullptr,nullptr,nullptr,CRYPTPROTECT_UI_FORBIDDEN,&out))throw std::runtime_error("기기 ID 보호 실패");try{atomicWrite(path,std::string((char*)out.pbData,out.cbData));}catch(...){LocalFree(out.pbData);throw;}LocalFree(out.pbData);}
 bool agreed(const std::string& scope,const std::string& version,const std::string& digest){auto records=state.value("consents",json::object());return records.contains(scope)&&str(records[scope],"version")==version&&str(records[scope],"digest")==digest&&flag(records[scope],"required");}
 bool hardware(const std::string& scope){return state.contains("consents")&&state["consents"].contains(scope)&&flag(state["consents"][scope],"hardware");}
 void accept(const std::string& scope,const std::string& version,const std::string& digest,bool optional){state["consents"][scope]={{"version",version},{"digest",digest},{"required",true},{"hardware",optional}};save();}
};
