inline json deviceHardware(){json result={{"os","Windows"}};OSVERSIONINFOW info{};info.dwOSVersionInfoSize=sizeof info;using GetVersion=LONG(WINAPI*)(OSVERSIONINFOW*);auto version=(GetVersion)GetProcAddress(GetModuleHandleW(L"ntdll.dll"),"RtlGetVersion");if(version&&version(&info)==0)result["os_version"]=std::to_string(info.dwMajorVersion)+"."+std::to_string(info.dwMinorVersion)+"."+std::to_string(info.dwBuildNumber);wchar_t cpu[256]={};DWORD bytes=sizeof cpu;if(RegGetValueW(HKEY_LOCAL_MACHINE,L"HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0",L"ProcessorNameString",RRF_RT_REG_SZ,nullptr,cpu,&bytes)==ERROR_SUCCESS)result["cpu"]=utf8(cpu);MEMORYSTATUSEX memory{sizeof memory};if(GlobalMemoryStatusEx(&memory))result["ram_bytes"]=memory.ullTotalPhys;Com<IDXGIFactory1> factory;SIZE_T largest=0;if(SUCCEEDED(CreateDXGIFactory1(IID_PPV_ARGS(&factory)))){for(UINT i=0;i<32;i++){Com<IDXGIAdapter1> adapter;auto status=factory->EnumAdapters1(i,&adapter);if(status==DXGI_ERROR_NOT_FOUND)break;if(FAILED(status)||!adapter)continue;DXGI_ADAPTER_DESC1 desc{};if(SUCCEEDED(adapter->GetDesc1(&desc))&&!(desc.Flags&DXGI_ADAPTER_FLAG_SOFTWARE)&&desc.DedicatedVideoMemory>=largest){largest=desc.DedicatedVideoMemory;result["gpu"]=utf8(desc.Description);result["vram_bytes"]=uint64_t(largest);}}}return result;}
inline void reviewConsent(const std::string& scope,const std::string& version,const std::string& digest,const std::string& text){if(deviceIdentity->agreed(scope,version,digest))return;if(sha256(text)!=digest)throw std::runtime_error("동의 문서 무결성 확인 실패");auto content=wide(text);TASKDIALOG_BUTTON buttons[]={{IDOK,L"필수 동의하고 계속"},{IDCANCEL,L"동의하지 않고 종료"}};TASKDIALOGCONFIG dialog{sizeof dialog};dialog.dwFlags=TDF_ALLOW_DIALOG_CANCELLATION|TDF_SIZE_TO_CONTENT;dialog.pszWindowTitle=L"snuwcanvas · 개발용 개인정보 안내";dialog.pszMainInstruction=L"필수 항목에 동의해야 서비스를 사용할 수 있습니다.";dialog.pszContent=L"개발용 초안이며 법률 검토 전입니다. 아래 상세 내용을 확인하세요. 선택 기기 정보 제공을 거부해도 생성 기능을 사용할 수 있습니다.";dialog.pszExpandedInformation=content.c_str();dialog.pszExpandedControlText=L"수집·보관·제공·거부권 전체 내용 보기";dialog.pszCollapsedControlText=L"전체 내용 접기";dialog.pszVerificationText=L"[선택] OS·CPU·RAM·GPU·VRAM 성능 정보 제공에 동의";dialog.cButtons=2;dialog.pButtons=buttons;dialog.nDefaultButton=IDCANCEL;int selected=IDCANCEL;BOOL optional=FALSE;check(TaskDialogIndirect(&dialog,&selected,nullptr,&optional),"동의 화면 표시 실패");if(selected!=IDOK)throw std::runtime_error("필수 동의가 거부되어 앱을 종료합니다.");deviceIdentity->accept(scope,version,digest,optional!=FALSE);}
