inline int foundationTest(const fs::path& folder){try{auto before=std::make_shared<DeviceIdentity>(folder);before->accept("test","draft-1",sha256("policy"),false);auto uuid=before->uuid;DeviceIdentity after(folder);if(uuid!=after.uuid||!after.agreed("test","draft-1",sha256("policy"))||after.hardware("test")||after.agreed("test","draft-2",sha256("policy")))throw std::runtime_error("protected identity/consent regression");if(sha256("abc")!="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad")throw std::runtime_error("hash regression");if(readFile(after.path).find(uuid)!=std::string::npos)throw std::runtime_error("identity persisted in plain text");atomicWrite(folder/"foundation-test-result.json",json{{"ok",true},{"gui_opened",false},{"client_version",CLIENT_VERSION},{"optional_hardware",false}}.dump(2));return 0;}catch(const std::exception& e){atomicWrite(folder/"foundation-test-result.json",json{{"ok",false},{"error",e.what()}}.dump(2));return 1;}}
